# Generated by manage.py generate_test_cases.
from datetime import timedelta

from django.urls import reverse
from django.utils import timezone
from rest_framework.test import APIClient

from bloomerp.models.application_field import ApplicationField
from bloomerp.models.audit.activity_log import ActivityLogAction
from bloomerp.models.files.page import Page
from bloomerp.models.users.user import User
from bloomerp.services.activity_log_services import ActivityLogManager
from bloomerp.tests.base import BloomerpModelTestCase, ModelScenario


class TestPageModel(BloomerpModelTestCase):
    """Verify the activity recorded for page operations and editor saves."""

    model = Page

    def setUp(self) -> None:
        """Create a page owner for the lifecycle and editor tests."""
        super().setUp()
        self.owner = User.objects.create_user(username="page-owner", is_superuser=True)

    def create_page(self) -> Page:
        """Create a page whose full content can be matched against its snapshots."""
        return Page.objects.create(owner=self.owner, title="Draft", content="<p>Original</p>")

    def has_creation_snapshot(self, page: Page) -> bool:
        """Check that the first activity entry contains the full saved page."""
        entry = ActivityLogManager(page).get_for_object().get(action=ActivityLogAction.CREATE)
        return entry.payload[0] == {"snapshot": {"title": page.title, "content": page.content}}

    def has_no_change_entry(self, page: Page) -> bool:
        """Check that a save without a title or content change stays out of the log."""
        return not ActivityLogManager(page).get_for_object().filter(action=ActivityLogAction.CHANGE).exists()

    def has_deletion_entry(self, page: Page) -> bool:
        """Check that deletion records an event without copying the page content."""
        entry = ActivityLogManager(page).get_for_object().get(action=ActivityLogAction.DELETE)
        return entry.payload == []

    def get_test_scenarios(self) -> list[ModelScenario[Page]]:
        """Cover creation, a bookkeeping-only save, and deletion in one lifecycle."""
        return [
            ModelScenario(
                name="Page activity records creation and deletion around a bookkeeping-only save",
                create_operation=self.create_page,
                create_validators=self.has_creation_snapshot,
                update_args={},
                update_validators=self.has_no_change_entry,
                delete_validators=self.has_deletion_entry,
            ),
        ]

    def test_editor_saves_share_one_snapshot_window_and_update_recents(self) -> None:
        """Exercise the generated Page API across editors and a 30-minute boundary."""
        page = self.create_page()
        editor = User.objects.create_user(username="page-editor", is_superuser=True)
        activity = ActivityLogManager(page)
        entries = activity.get_for_object()
        ApplicationField.objects.get_or_create(
            content_type=activity.get_content_type(), field="content", defaults={"field_type": "text"}
        )
        url = reverse("pages-detail", kwargs={"pk": page.pk})
        client = APIClient()

        client.force_login(editor)
        content = "<p>First edit</p>"
        response = client.patch(url, {"content": content}, format="json")
        self.assertEqual(response.status_code, 200, response.data)
        change = entries.get(action=ActivityLogAction.CHANGE)
        self.assertEqual(change.actor, editor)
        self.assertEqual(change.payload, [{"field": "content"}, {"field": "updated_by"}])
        self.assertEqual(list(Page.recent_for(editor)), [page])

        entries.filter(action=ActivityLogAction.CREATE).update(
            timestamp=timezone.now() - timedelta(minutes=30)
        )
        client.force_login(self.owner)
        response = client.patch(url, {"title": "After 30 minutes"}, format="json")
        self.assertEqual(response.status_code, 200, response.data)
        snapshot = entries.get(action=ActivityLogAction.CHANGE, actor=self.owner)
        self.assertEqual(snapshot.payload, [
            {"snapshot": {"title": "After 30 minutes", "content": content}},
            {"field": "title"},
            {"field": "updated_by"},
        ])
        self.assertEqual(list(Page.recent_for(self.owner)), [page])

        client.force_login(editor)
        response = client.patch(url, {"title": "Another edit"}, format="json")
        self.assertEqual(response.status_code, 200, response.data)
        self.assertEqual(entries.filter(payload__0__snapshot__isnull=False).count(), 2)
